Method.Source:
/// <summary>
/// ShipmentId parameter
/// </summary>
/// <param name = "_shipmentId">purchId</param>
/// <returns>purchId</returns>
[
    DataMemberAttribute("PurchId"),
    SysOperationLabelAttribute(literalStr("Purchase order")),
    SysOperationControlVisibilityAttribute(false)

]
public PurchId parmPurchId(PurchId _purchId = purchId)
{
    purchId = _purchId;

    return purchId;
}

/// <summary>
/// Invoice journal recid parameter
/// </summary>
/// <param name = "_InvVoucherRecId">Invoice journal recid</param>
/// <returns>Invoice journal recid.</returns>
[
    DataMemberAttribute("InvoiceJour"),
    SysOperationLabelAttribute(literalStr("Invoice journal")),
    SysOperationControlVisibilityAttribute(false)

]
public RecID parmInvJourRecId(RecID _InvVoucherRecId = invVoucherRecId)
{
    invVoucherRecId = _InvVoucherRecId;

    return invVoucherRecId;
}

/// <summary>
/// Reprint parameter
/// </summary>
/// <param name = "_isReprint">Reprint</param>
/// <returns>Boolean value</returns>
[
    DataMemberAttribute("IsReprint"),
    SysOperationLabelAttribute(literalStr("Reprint")),
    SysOperationControlVisibilityAttribute(false)

]
public boolean parmIsRePrint(boolean _isReprint = isReprint)
{
    isReprint = _isReprint;

    return isReprint;
}
